def second_largest_quantity(quantities):
    first = second = float('-inf')
    for q in quantities:
        if q > first:
            second = first  # old max becomes second
            first = q
        elif q > second and q != first:
            second = q
    # If no distinct second found, return first
    return second if second != float('-inf') else first

