def fleet_queries(fuel, updates, queries):
    arr = fuel[:]
    for l, r, v in updates:
        for i in range(l, r + 1):
            arr[i] += v
    results = []
    for l, r in queries:
        results.append(sum(arr[l:r+1]))
    return results

def longest_window_at_most_k(packets, k):
    if k == 0:
        return 0
    n = len(packets)
    max_len = 0
    for i in range(n):
        seen = set()
        for j in range(i, n):
            seen.add(packets[j])
            if len(seen) <= k:
                max_len = max(max_len, j - i + 1)
            else:
                break
    return max_len
